"""Build a self-contained, offline review page from this project's own scene."""
import base64,json,pathlib
root=pathlib.Path(__file__).resolve().parents[1]
fonts=root.parents[1]/'assets/fonts'
b64=lambda p:base64.b64encode(p.read_bytes()).decode()
css=f'''@font-face{{font-family:Montserrat;src:url(data:font/ttf;base64,{b64(fonts/'Montserrat/Montserrat[wght].ttf')});font-weight:100 900}}@font-face{{font-family:"Instrument Serif";src:url(data:font/ttf;base64,{b64(fonts/'Instrument Serif/InstrumentSerif-Italic.ttf')})}}'''
scene=(root/'src/scene.mjs').read_text().replace('export function draw','function draw')
logo=json.loads((root/'assets/logo.json').read_text())['base64']
beats=(root/'plan/beats.json').read_text()
html='''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Glowfy · Propuesta visual</title><style>__FONTS__
*{box-sizing:border-box}body{margin:0;background:#f6f0f8;color:#23152f;font-family:Montserrat,Arial,sans-serif}header{padding:30px 6vw;border-bottom:1px solid #e3d7e9;display:flex;justify-content:space-between;font-size:13px}main{max-width:1200px;margin:auto;padding:56px 40px;display:grid;grid-template-columns:1fr 390px;gap:70px;align-items:center}.tag{font-size:12px;letter-spacing:.16em;color:#79528d;text-transform:uppercase}h1{font-size:64px;line-height:1.02;font-weight:600;letter-spacing:-.04em;margin:24px 0}h1 em{display:block;font:italic 90px/1.04 "Instrument Serif";color:#63318a}p{line-height:1.8;max-width:490px;color:#6b5974;font-size:15px}.stages{padding:24px 0;border-top:1px solid #ddcfe5;margin-top:30px}.stages div{display:flex;gap:20px;margin:18px 0;font-size:14px}.stages b{color:#ad52e0;font-size:12px}.small{font-size:11px;line-height:1.7}.viewer{background:#fff;border-radius:28px;overflow:hidden;box-shadow:0 24px 70px #36194615}canvas{display:block;width:100%;height:auto}.controls{padding:18px;display:flex;gap:15px;align-items:center}button{border:0;border-radius:30px;padding:12px 18px;background:#63318a;color:white;font-family:inherit;cursor:pointer}input{width:100%;accent-color:#ad52e0}.keyframes{max-width:1200px;padding:0 40px 60px;margin:auto;display:grid;grid-template-columns:repeat(3,1fr);gap:24px}.keyframes figure{margin:0}.keyframes canvas{border-radius:16px}.keyframes figcaption{padding-top:14px;font-size:13px;color:#79528d}footer{max-width:1120px;margin:0 auto 40px;font-size:11px;color:#79528d;line-height:1.8}a{color:inherit}@media(max-width:800px){main{grid-template-columns:1fr;padding:32px 24px;gap:25px}h1{font-size:44px}h1 em{font-size:65px}.viewer{max-width:390px;width:100%;margin:auto}.keyframes{padding:10px 24px 40px;gap:12px}footer{padding:0 24px}.keyframes figcaption{font-size:10px}}
</style><header><span>GLOWFY / DIRECCIÓN VISUAL</span><span>PROPUESTA 01</span></header><main><section><div class="tag">Manicuristas · Vertical · 12 segundos</div><h1>Tus manos,<em>tu talento.</em></h1><p>Los mensajes llegan mientras estás creando. La cámara pasa de la mesa de manicura al teléfono: Glowfy continúa la conversación hasta una cita.</p><div class="stages"><div><b>01</b><span>El oficio y la interrupción.</span></div><div><b>02</b><span>Una conversación que avanza.</span></div><div><b>03</b><span>Una invitación: conoce Glowfy.</span></div></div><p class="small">Muestra para revisar composición y movimiento. Interfaz ilustrativa. Sin narración. El MP4 incluye efectos breves de interfaz; esta vista es silenciosa. Pendiente de tu revisión, sin publicación.</p></section><section class="viewer"><canvas id="main" width="540" height="960" aria-label="Vista previa de Glowfy"></canvas><div class="controls"><button id="play">Reproducir</button><input id="time" type="range" min="0" max="11.999" step="0.01" value="0" aria-label="Recorrer la animación"></div></section></main><section class="keyframes"><figure><canvas id="key0" width="540" height="960"></canvas><figcaption>La situación · 1,8 s</figcaption></figure><figure><canvas id="key1" width="540" height="960"></canvas><figcaption>La conversación · 8 s</figcaption></figure><figure><canvas id="key2" width="540" height="960"></canvas><figcaption>El siguiente paso · 11 s</figcaption></figure></section><footer>Identidad recuperada de <a href="https://getglowfy.com/">getglowfy.com</a>. Montserrat e Instrument Serif: SIL Open Font License. Ilustración, animación y efectos de sonido creados para esta propuesta. Las versiones anteriores se conservan.</footer><script>
__SCENE__
const beats=__BEATS__,logo=new Image();logo.src='data:image/png;base64,__LOGO__';
let playing=false,origin=0,time=0;const main=document.querySelector('#main'),slider=document.querySelector('#time'),button=document.querySelector('#play');
const paint=(canvas,t)=>draw(canvas.getContext('2d'),t,{width:canvas.width,height:canvas.height,beats,logo});
async function init(){await Promise.all([document.fonts.load('600 40px Montserrat'),document.fonts.load('400 40px "Instrument Serif"'),logo.decode()]);await document.fonts.ready;paint(main,0);[1.8,8,11].forEach((t,i)=>paint(document.querySelector('#key'+i),t));window.reviewReady=true;requestAnimationFrame(tick)}
function tick(now){if(playing){time=(now-origin)/1000;if(time>=12){time=11.999;playing=false;button.textContent='Repetir'}slider.value=time;paint(main,time)}requestAnimationFrame(tick)}
button.onclick=()=>{playing=!playing;if(playing){if(time>=11.99)time=0;origin=performance.now()-time*1000}button.textContent=playing?'Pausar':'Reproducir'};
slider.oninput=()=>{time=Number(slider.value);origin=performance.now()-time*1000;paint(main,time)};init();
</script></html>'''
html=html.replace('__FONTS__',css).replace('__SCENE__',scene).replace('__BEATS__',beats).replace('__LOGO__',logo)
(root/'plan/design.html').write_text(html)
print('Review page created; embedded project graphics and OFL fonts; no network required.')
